/***/ "./node_modules/raw-loader/index.js!./src/app/Components/ControllerContainer/controller-instructions/controller-instructions.component.html":
/*!*****************************************************************************************************************************************!*\
  !*** ./node_modules/raw-loader!./src/app/Components/ControllerContainer/controller-instructions/controller-instructions.component.html ***!
  \*****************************************************************************************************************************************/
/*! no static exports found */
/***/ (function(module, exports) {

module.exports = "<div class=\"container mt-4 mb-3\">\n        <div class=\"col-sm-12\">\n            <div style=\"height: 91%; width: 100%; overflow: auto;\">\n                <div style=\"text-align: center;\">\n                    <span style=\"font-size:22px;\">\n                    <strong><u>Instructions</u></strong>\n                </span>\n            </div>\n             <br>\n                <br>\n                <!-- <div style=\"text-align: center;\"><strong><span style=\"background-color:#FFFF00;\">\n                            {{user?.courseCode}}: {{user?.courseName}}\n                        </span></strong></div> -->\n                <!-- <p style=\"text-align:left;\"><em>Duration</em> : <strong>{{user?.examDuration}} </strong><span\n                        style=\"float:right;\"><em>Total Marks</em> : <strong>{{user?.totalMark}}</strong></span></p> -->\n                <strong>Read the\n                    following instructions carefully</strong>\n                    <br>\n                    <br>\n                <ol>\n                    <li>The Invigilator must ensure that all the systems allocated in the respective hall are suitable for conducting the respective examination.</li>\n                </ol>\n                <ol>\n                    <li value=\"2\">The Invigilator is to ensure that all candidates have presented their respective Hall Tickets before entering the examination hall.</li>\n                </ol>\n                <ol>\n                    <li value=\"3\">\n                        Candidates may only be permitted to the exam hall after confirmation by the invigilator using the facial recognition software.\n                    </li>\n                </ol>\n                <ol>\n                    <li value=\"4\">Candidates are permitted to occupy their allotted seats \n                       <strong>30 minutes</strong>  \n                        before the scheduled start of the examination.</li>\n                </ol>\n                <ol>\n                    <li value=\"5\">The examination will commence only after all the candidates who have been \n                        verified by the\n                        <strong>facial recognition</strong>  \n                         software, logs in to their respective account.</li>\n                </ol>\n                <ol>\n                    <li value=\"6\">The Invigilator must ensure that all candidates are occupying their allocated systems only.</li>\n                </ol>\n                <ol>\n                    <li value=\"7\">The Invigilator has the authority to shuffle the questions as per the number of candidates appearing for the examination.</li>\n                </ol>\n                <ol>\n                    <li value=\"8\">The examination must begin at the pre-defined time unless and until communications from official channels intervene.</li>\n                </ol>\n                <ol>\n                    <li value=\"9\">The Invigilator has the authority to resume the examination of a candidate who had exited their examination screen.</li>\n                </ol>\n                <ol>\n                    <li value=\"10\">The Invigilator has the authority to mark <strong>SMP (Suspected Malpractice)</strong> for a candidate after repeated exam log out or if found to be indulged in any sort of malpractice.</li>\n                </ol>\n                <ol>\n                    <li value=\"11\">Candidates are not permitted to leave the examination hall before the end of the examination.</li>\n                </ol>\n                <ol>\n                    <li value=\"12\">The Invigilator must ensure that all candidates that have appeared for the examination submit their answers</li>\n                </ol>\n                <ol>\n                    <li value=\"13\">The Invigilator can manually submit the answer of any candidate after the examination time has elapsed.</li>\n                </ol>\n                <ol>\n                    <li value=\"14\">The Invigilator can know the status of any student anytime during the examination period.</li>\n                </ol>\n            </div>\n            <div class=\"row\" *ngIf=\"showConfirmation\">\n                <mat-card>\n                    <small class=\"font-weight-bold\">\n                        <mat-checkbox [(ngModel)]=\"checked\" color=\"primary\">\n                        </mat-checkbox> I have read and understood the instructions.\n                        All computer hardware allotted to me are in proper\n                        working condition. I agree that in case of not adhering to the instructions, I shall be liable to\n                        be debarred from this Test and/or to disciplinary action, which may include ban from future Tests /\n                        Examinations.\n                    </small>\n                </mat-card>\n            </div>\n            <div *ngIf=\"showConfirmation\" class=\"row p-2 d-flex justify-content-center\">\n                <button [disabled]=\"!checked || !examFetchCompleted\" (click)=\"Accept()\" matTooltip=\"Proceed\" mat-raised-button\n                    class=\"Submit\">\n                    Accept and Start\n                </button>\n            </div>\n        </div>\n    </div>"

/***/ }),

