module.exports = "<!-- <div class=\"p-0 vh-100\" style=\"background-image:url(../../../assets/Images/exam.jpg)\"> -->\n<div class=\"container\">\n    <div class=\"row d-flex justify-content-center\">\n        <div class=\"col-sm-4\" style=\"margin-top: 10%\">\n            <mat-card class=\"p-0 mat-elevation-z8\">\n                <mat-card-header class=\"p-2 d-flex justify-content-center CardHeader\">\n                    <mat-card-title class=\"Header mb-0\">\n                        Invigilator Login\n                    </mat-card-title>\n                </mat-card-header>\n                <mat-card-content class=\"mt-3\">\n                    <form [formGroup]=\"loginForm\" (ngSubmit)=\"Submit()\">\n                        <div class=\"col-sm-12\">\n                            <mat-form-field class=\"w-100\" appearance=\"outline\">\n                                <mat-label>{{loginFormCaption?.caption1}}</mat-label>\n                                <input matInput formControlName=\"email\" [placeholder]=\"loginFormCaption?.caption1\"\n                                    required>\n                                <mat-icon matSuffix>person</mat-icon>\n                                <mat-error *ngIf=\"loginForm?.get('email').hasError('required')\">\n                                    {{ERROR?.required}}\n                                </mat-error>\n                                <mat-error *ngIf=\"loginForm?.get('email').hasError('pattern')\">\n                                    {{ERROR?.emailPattern}}\n                                </mat-error>\n                            </mat-form-field>\n                        </div>\n                        <div class=\"col-sm-12\">\n                            <mat-form-field class=\"w-100\" appearance=\"outline\">\n                                <mat-label>{{loginFormCaption?.caption2}}</mat-label>\n                                <input matInput formControlName=\"password\" [type]=\"showPass ? 'text' : 'password'\"\n                                    [placeholder]=\"loginFormCaption?.caption2\" required>\n                                <button type=\"button\" style=\"outline: none;\" (click)=\"togglePass()\" matSuffix\n                                    mat-icon-button>\n                                    <mat-icon>{{passIcon}}</mat-icon>\n                                </button>\n                                <mat-error *ngIf=\"loginForm?.get('password').hasError('required')\">\n                                    {{ERROR?.required}}\n                                </mat-error>\n                            </mat-form-field>\n                        </div>\n                        <!-- <div class=\"col-sm-12\">\n                                <div #recaptcha ></div>\n                              </div> -->\n                        <div class=\"col-sm-12 p-2 d-flex justify-content-center\">\n                            <button [disabled]=\"loginForm?.invalid\" mat-raised-button class=\"Submit\">Login</button>\n                        </div>\n                    </form>\n                </mat-card-content>\n            </mat-card>\n        </div>\n    </div>\n</div>\n<!-- </div> -->"

